contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint _val) public payable {
        uint balBefore = address(c).balance;
        c.SetMinSum(_val); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;
        uint minSumAfter = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(minSumAfter == _val && balAfter == balBefore);
    }
}

