pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 _val) internal {
        uint balBefore = address(c).balance;
        try c.SetMinSum(_val) {} catch { return; }
        uint balAfter = address(c).balance;
        uint256 minSumAfter;
        try c.MinSum() returns (uint256 __r) { minSumAfter = __r; } catch { return; }
        assertTrue(minSumAfter == _val && balAfter == balBefore);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
